from datetime import date; from decimal import Decimal; from uuid import uuid4; import pytest; from fastapi import status; from httpx import AsyncClient; from sqlalchemy import event, select; from src.audit import STATEMENT_SOURCE_TYPES, TraceRecordType, TraceResult; from src.audit.orm import TraceRecordRow; from src.extraction import BankStatementStatus, DispositionPolicy, DocumentType, TransactionClassification, TransactionDirection, UploadedDocument; from src.extraction.orm.layer2 import AtomicTransaction; from src.extraction.orm.statement_summary import StatementSummary; from src.identity import User; from src.ledger import Account, AccountType, Direction, JournalEntry, post_journal_entry, submit_manual_journal_entry, validate_manual_journal_entry_for_post; from src.reconciliation import ReconciliationMatch, ReconciliationStatus, ReviewedDispositionDependencies; from src.routers import reconciliation as reconciliation_router; from src.schemas.reconciliation import ReconciliationStatusEnum, ReviewedDispositionRequest
async def create_test_statement(db, user: User, **kwargs) -> StatementSummary: document = UploadedDocument(user_id=user.id, file_path='statements/test.pdf', file_hash=f'hash_{uuid4().hex[:8]}', original_filename='test.pdf', document_type=DocumentType.BANK_STATEMENT); db.add(document); await db.flush(); defaults = {'id': uuid4(), 'user_id': user.id, 'uploaded_document_id': document.id, 'file_hash': document.file_hash, 'institution': 'Test Bank', 'currency': 'SGD', 'status': BankStatementStatus.PARSED}; defaults.update(kwargs); statement = StatementSummary(**defaults); db.add(statement); await db.flush(); return statement
async def create_test_asset_account(db, user: User) -> Account: account = Account(user_id=user.id, name=f'Mapped Bank {uuid4().hex[:8]}', type=AccountType.ASSET, currency='SGD'); db.add(account); await db.flush(); return account
def create_test_transaction(db, statement: StatementSummary, **kwargs) -> AtomicTransaction: kwargs.pop('status', None); defaults = {'id': uuid4(), 'user_id': statement.user_id, 'txn_date': date(2024, 1, 15), 'description': 'Test transaction', 'amount': Decimal('100.00'), 'direction': TransactionDirection.OUT, 'currency': 'SGD', 'dedup_hash': uuid4().hex + uuid4().hex, 'source_documents': [{'doc_id': str(statement.uploaded_document_id), 'doc_type': DocumentType.BANK_STATEMENT.value}]}; defaults.update(kwargs); return AtomicTransaction(**defaults)
def create_test_match(db, transaction: AtomicTransaction, **kwargs) -> ReconciliationMatch: defaults = {'id': uuid4(), 'atomic_txn_id': transaction.id, 'status': ReconciliationStatus.PENDING_REVIEW, 'match_score': 85, 'journal_entry_ids': []}; defaults.update(kwargs); return ReconciliationMatch(**defaults)
async def create_anchored_match_entry(db, *, user_id, bank_account: Account, counter_account: Account, entry_date: date, memo: str, amount: Decimal) -> JournalEntry: entry = await submit_manual_journal_entry(db, user_id=user_id, entry_date=entry_date, memo=memo, rationale=f'Test operator attested reconciliation candidate: {memo}', lines_data=[{'account_id': counter_account.id, 'direction': Direction.DEBIT, 'amount': amount, 'currency': 'SGD'}, {'account_id': bank_account.id, 'direction': Direction.CREDIT, 'amount': amount, 'currency': 'SGD'}], base_currency='SGD'); await db.refresh(entry, ['lines']); await validate_manual_journal_entry_for_post(db, user_id=user_id, entry=entry, base_currency='SGD'); return await post_journal_entry(db, entry.id, user_id, base_currency='SGD')
async def _seed_router_txns(db, user: User, count: int=1, statement: StatementSummary | None=None) -> tuple[StatementSummary, list[AtomicTransaction]]: stmt = statement or await create_test_statement(db, user); txns = [create_test_transaction(db, stmt) for _ in range(count)]; db.add_all(txns); await db.commit(); return (stmt, txns)
async def _seed_router_matches(db, user: User, statuses: list[ReconciliationStatus], statement: StatementSummary | None=None) -> tuple[StatementSummary, list[AtomicTransaction], list[ReconciliationMatch]]: stmt = statement or await create_test_statement(db, user); txns = [create_test_transaction(db, stmt) for _ in statuses]; db.add_all(txns); matches = [create_test_match(db, txn, status=s) for txn, s in zip(txns, statuses)]; db.add_all(matches); await db.commit(); return (stmt, txns, matches)
async def _seed_router_match(db, user: User, *, status: ReconciliationStatus=ReconciliationStatus.PENDING_REVIEW, score: int=85, journal_entry_ids: list[str] | None=None, statement: StatementSummary | None=None) -> tuple[StatementSummary, AtomicTransaction, ReconciliationMatch]:
    stmt = statement or await create_test_statement(db, user); txn = create_test_transaction(db, stmt); db.add(txn)
    match = create_test_match(db, txn, status=status, match_score=score, journal_entry_ids=journal_entry_ids or []); db.add(match); await db.commit(); return (stmt, txn, match)
async def _seed_expense_setup(db, user: User, *, expense_name: str='Expense') -> tuple[Account, StatementSummary, AtomicTransaction, Account]: account = await create_test_asset_account(db, user); statement = await create_test_statement(db, user, account_id=account.id, currency='SGD'); expense = Account(user_id=user.id, name=f'{expense_name} {uuid4().hex[:8]}', type=AccountType.EXPENSE, currency='SGD'); transaction = create_test_transaction(db, statement); db.add_all([expense, transaction]); await db.commit(); return (account, statement, transaction, expense)
