    async def test_accept_match_success(self, client: AsyncClient, db, test_user: User):
        'AC-reconciliation.review-queue.3'; account, _, transaction, counter_account = await _seed_expense_setup(db, test_user, expense_name='Matched expense'); entry = await create_anchored_match_entry(db, user_id=test_user.id, bank_account=account, counter_account=counter_account, entry_date=transaction.txn_date, memo=f'Reviewed candidate {transaction.id}', amount=transaction.amount)
        match = create_test_match(db, transaction, journal_entry_ids=[str(entry.id)]); db.add(match); await db.commit(); response = await client.post(f'/reconciliation/matches/{match.id}/accept'); assert response.status_code == status.HTTP_200_OK; assert response.json()['status'] == ReconciliationStatusEnum.ACCEPTED.value
