    async def test_reject_match_not_found(self, client: AsyncClient, test_user: User): 'AC-reconciliation.review-queue.6 AC4.3.7'; non_existent_id = str(uuid4()); response = await client.post(f'/reconciliation/matches/{non_existent_id}/reject'); assert response.status_code == status.HTTP_404_NOT_FOUND; assert 'Match' in response.json()['detail']
    async def test_batch_accept_success(self, client: AsyncClient, db, test_user: User):
        'AC4.2.1'; account, statement, txn1, expense = await _seed_expense_setup(db, test_user, expense_name='Batch Expense'); txn2 = create_test_transaction(db, statement); db.add(txn2); await db.commit(); entries = []
        for transaction in (txn1, txn2): entry = await create_anchored_match_entry(db, user_id=test_user.id, bank_account=account, counter_account=expense, entry_date=transaction.txn_date, memo=f'Pre-existing batch candidate {transaction.id}', amount=transaction.amount); entries.append(entry)
        await db.flush(); match1 = create_test_match(db, txn1, status=ReconciliationStatus.PENDING_REVIEW, journal_entry_ids=[str(entries[0].id)]); match2 = create_test_match(db, txn2, status=ReconciliationStatus.PENDING_REVIEW, journal_entry_ids=[str(entries[1].id)]); db.add_all([match1, match2]); await db.commit(); payload = {'match_ids': [str(match1.id), str(match2.id)]}; response = await client.post('/reconciliation/batch-accept', json=payload); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert isinstance(data, dict); assert 'items' in data; assert 'total' in data
