    async def test_user_isolation(self, client: AsyncClient, db, test_user: User): 'AC-reconciliation.review-queue.12 AC4.3.13'; other_user = User(email='other@example.com', hashed_password='hashed'); db.add(other_user); await db.commit(); _, (other_transaction,) = await _seed_router_txns(db, other_user, count=1); response = await client.get('/reconciliation/unmatched'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert all((str(item.get('id')) != str(other_transaction.id) for item in data.get('items', [])))
