    async def test_list_matches_with_entry_summaries(self, client: AsyncClient, db, test_user: User): 'AC4.3.14'; from src.ledger import Account, AccountType, JournalEntryStatus, JournalLine; account = Account(id=uuid4(), user_id=test_user.id, name='Test Account', type=AccountType.ASSET, currency='SGD'); db.add(account); await db.commit(); entry = JournalEntry(id=uuid4(), user_id=test_user.id, entry_date=date.today(), memo='Test entry', status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); from src.ledger import Direction; line1 = JournalLine(id=uuid4(), journal_entry_id=entry.id, account_id=account.id, direction=Direction.DEBIT, amount=Decimal('100.00'), currency='SGD'); line2 = JournalLine(id=uuid4(), journal_entry_id=entry.id, account_id=account.id, direction=Direction.CREDIT, amount=Decimal('100.00'), currency='SGD'); db.add_all([line1, line2]); await db.commit(); await _seed_router_match(db, test_user, journal_entry_ids=[str(entry.id)]); response = await client.get('/reconciliation/matches'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert len(data['items']) >= 1; match_data = data['items'][0]; assert 'entries' in match_data; assert len(match_data['entries']) > 0, 'Expected entry summaries to be populated'; assert 'id' in match_data['entries'][0]; assert 'total_amount' in match_data['entries'][0]
